// Writes src/tokenCss.generated.ts from ../mobile/src/global.css.
// `--check` exits 1 when the committed file is stale.
import { readFileSync, writeFileSync } from "node:fs";
import { tokenCss } from "./tokenCss.mjs";

const source = new URL("../../mobile/src/global.css", import.meta.url);
const target = new URL("../src/tokenCss.generated.ts", import.meta.url);

const output =
  "// Generated by scripts/gen-token-css.mjs from mobile/src/global.css. Do not edit.\n" +
  `export const TOKEN_CSS: string = ${JSON.stringify(tokenCss(readFileSync(source, "utf8")))};\n`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch {
    // missing file counts as stale
  }
  if (current !== output) {
    console.error("src/tokenCss.generated.ts is stale. Run: npm run gen:tokens");
    process.exit(1);
  }
} else {
  writeFileSync(target, output);
}
